#### REQ-LENS-007-005: Lineage Visualization

**Status**: Mandatory (Phase 2)
**Rationale**: Interactive graph for data flow exploration

**Visualization Features**:
- Graph view: Nodes (producers, topics, consumers) and edges (data flow)
- Filter by business unit, application, time range
- Highlight critical paths (production flows)
- Zoom/pan for large graphs (100+ nodes)
- Export to PNG/SVG for documentation

**Implementation**:

**React Component with D3.js Lineage Graph**:
```javascript
import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';

const LineageGraphVisualization = ({ topicName, businessUnit, timeRange }) => {
  const svgRef = useRef();
  const [graphData, setGraphData] = useState(null);
  const [selectedNode, setSelectedNode] = useState(null);

  useEffect(() => {
    // Fetch lineage data from Lenses API
    const fetchLineageData = async () => {
      const response = await fetch(
        `/api/lineage/graph?topic=${topicName}&business_unit=${businessUnit}&time_range=${timeRange}`,
        { headers: { 'Authorization': `Bearer ${localStorage.getItem('token')}` } }
      );
      const data = await response.json();
      setGraphData(data);
    };

    fetchLineageData();
  }, [topicName, businessUnit, timeRange]);

  useEffect(() => {
    if (!graphData) return;

    const width = 1200;
    const height = 800;

    // Clear previous graph
    d3.select(svgRef.current).selectAll('*').remove();

    const svg = d3.select(svgRef.current)
      .attr('width', width)
      .attr('height', height)
      .attr('viewBox', `0 0 ${width} ${height}`);

    // Create force simulation
    const simulation = d3.forceSimulation(graphData.nodes)
      .force('link', d3.forceLink(graphData.edges)
        .id(d => d.id)
        .distance(150))
      .force('charge', d3.forceManyBody().strength(-300))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(50));

    // Add zoom behavior
    const zoomBehavior = d3.zoom()
      .scaleExtent([0.5, 3])
      .on('zoom', (event) => {
        container.attr('transform', event.transform);
      });

    svg.call(zoomBehavior);

    const container = svg.append('g');

    // Draw edges
    const links = container.append('g')
      .selectAll('line')
      .data(graphData.edges)
      .join('line')
      .attr('stroke', d => {
        switch(d.type) {
          case 'produces': return '#4CAF50';
          case 'consumes': return '#2196F3';
          case 'transforms': return '#FF9800';
          default: return '#999';
        }
      })
      .attr('stroke-width', 2)
      .attr('stroke-opacity', 0.6)
      .attr('marker-end', 'url(#arrowhead)');

    // Add arrowhead marker
    svg.append('defs').append('marker')
      .attr('id', 'arrowhead')
      .attr('viewBox', '-0 -5 10 10')
      .attr('refX', 25)
      .attr('refY', 0)
      .attr('orient', 'auto')
      .attr('markerWidth', 8)
      .attr('markerHeight', 8)
      .append('svg:path')
      .attr('d', 'M 0,-5 L 10 ,0 L 0,5')
      .attr('fill', '#999');

    // Draw nodes
    const nodes = container.append('g')
      .selectAll('circle')
      .data(graphData.nodes)
      .join('circle')
      .attr('r', 20)
      .attr('fill', d => {
        switch(d.type) {
          case 'producer': return '#4CAF50';
          case 'consumer': return '#2196F3';
          case 'topic': return '#FF9800';
          default: return '#999';
        }
      })
      .attr('stroke', '#fff')
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .on('click', (event, d) => setSelectedNode(d))
      .call(d3.drag()
        .on('start', dragstarted)
        .on('drag', dragged)
        .on('end', dragended));

    // Add node labels
    const labels = container.append('g')
      .selectAll('text')
      .data(graphData.nodes)
      .join('text')
      .text(d => d.label || d.id)
      .attr('font-size', 12)
      .attr('dx', 25)
      .attr('dy', 5)
      .style('pointer-events', 'none');

    // Update positions on simulation tick
    simulation.on('tick', () => {
      links
        .attr('x1', d => d.source.x)
        .attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x)
        .attr('y2', d => d.target.y);

      nodes
        .attr('cx', d => d.x)
        .attr('cy', d => d.y);

      labels
        .attr('x', d => d.x)
        .attr('y', d => d.y);
    });

    function dragstarted(event, d) {
      if (!event.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    }

    function dragged(event, d) {
      d.fx = event.x;
      d.fy = event.y;
    }

    function dragended(event, d) {
      if (!event.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    }

  }, [graphData]);

  const exportGraph = (format) => {
    const svgElement = svgRef.current;

    if (format === 'png') {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      const img = new Image();
      const svgData = new XMLSerializer().serializeToString(svgElement);
      const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);

      img.onload = () => {
        canvas.width = 1200;
        canvas.height = 800;
        ctx.drawImage(img, 0, 0);
        canvas.toBlob(blob => {
          const link = document.createElement('a');
          link.download = `lineage-${topicName || 'graph'}.png`;
          link.href = URL.createObjectURL(blob);
          link.click();
        });
      };
      img.src = url;
    } else if (format === 'svg') {
      const svgData = new XMLSerializer().serializeToString(svgElement);
      const blob = new Blob([svgData], { type: 'image/svg+xml' });
      const link = document.createElement('a');
      link.download = `lineage-${topicName || 'graph'}.svg`;
      link.href = URL.createObjectURL(blob);
      link.click();
    }
  };

  return (
    <div>
      <div style={{ marginBottom: '10px' }}>
        <button onClick={() => exportGraph('png')}>Export as PNG</button>
        <button onClick={() => exportGraph('svg')}>Export as SVG</button>
      </div>
      <svg ref={svgRef}></svg>
      {selectedNode && (
        <div style={{ position: 'absolute', right: 0, top: 0, width: '300px', padding: '10px', background: '#f5f5f5' }}>
          <h3>{selectedNode.label}</h3>
          <p><strong>Type:</strong> {selectedNode.type}</p>
          <p><strong>ID:</strong> {selectedNode.id}</p>
          {selectedNode.metadata && (
            <pre>{JSON.stringify(selectedNode.metadata, null, 2)}</pre>
          )}
        </div>
      )}
    </div>
  );
};

export default LineageGraphVisualization;
```
